package io.github.rivomesh;

import io.github.rivomesh.cdc.Cell;
import io.github.rivomesh.cdc.Change;
import io.github.rivomesh.cdc.TableSchema;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Reads row images from the bounded SQL shapes generated by Oracle LogMiner. */
final class OracleRedoDml {
    private static final Pattern TOKEN=Pattern.compile("\\G\\s*(?:"
            +"\"((?:[^\"]|\"\")*+)\"|'((?:[^']|'')*+)'|"
            +"([A-Za-z][A-Za-z0-9_$#]*)|([+-]?[0-9]+(?:\\.[0-9]+)?)|([.(),=;]))");

    private OracleRedoDml(){}

    static Change decode(TableSchema schema,String operation,String redo,String undo)throws Exception{
        Change.Operation expected;
        try{expected=Change.Operation.valueOf(operation);}
        catch(IllegalArgumentException unsupported){throw invalid("ORACLE_REDO_OPERATION_UNSUPPORTED");}
        Statement forward=new Parser(redo).parse();
        Statement reverse=new Parser(undo).parse();
        if(forward.operation!=expected||!schema.database.equals(forward.owner)||!schema.name.equals(forward.table)
                ||!forward.owner.equals(reverse.owner)||!forward.table.equals(reverse.table))
            throw invalid("ORACLE_REDO_TABLE_OR_OPERATION_MISMATCH");
        Map<String,String> before=null,after=null;
        switch(expected){
            case INSERT:
                requireInverse(reverse,Change.Operation.DELETE);
                after=forward.values;
                verifySubset(reverse.predicates,after);
                break;
            case DELETE:
                requireInverse(reverse,Change.Operation.INSERT);
                before=reverse.values;
                verifySubset(forward.predicates,before);
                break;
            case UPDATE:
                requireInverse(reverse,Change.Operation.UPDATE);
                if(!forward.values.keySet().equals(reverse.values.keySet()))
                    throw invalid("ORACLE_REDO_UNDO_SET_MISMATCH");
                before=new LinkedHashMap<>(forward.predicates);
                merge(before,reverse.values);
                after=new LinkedHashMap<>(before);
                after.putAll(forward.values);
                verifySubset(reverse.predicates,after);
                break;
            default:throw invalid("ORACLE_REDO_OPERATION_UNSUPPORTED");
        }
        Change event=new Change();
        event.operation=expected;
        event.tableId=schema.id;
        event.schemaVersion=schema.version;
        if(before!=null)event.before=typed(schema,before);
        if(after!=null)event.after=typed(schema,after);
        return event;
    }

    private static void requireInverse(Statement reverse,Change.Operation inverse){
        if(reverse.operation!=inverse)throw invalid("ORACLE_REDO_UNDO_MISMATCH");
    }

    private static void merge(Map<String,String> image,Map<String,String> additions){
        for(Map.Entry<String,String> entry:additions.entrySet()){
            if(image.containsKey(entry.getKey())&&!Objects.equals(image.get(entry.getKey()),entry.getValue()))
                throw invalid("ORACLE_REDO_UNDO_MISMATCH");
            image.put(entry.getKey(),entry.getValue());
        }
    }

    private static void verifySubset(Map<String,String> subset,Map<String,String> image){
        for(Map.Entry<String,String> entry:subset.entrySet()){
            if(!image.containsKey(entry.getKey())||!Objects.equals(image.get(entry.getKey()),entry.getValue()))
                throw invalid("ORACLE_REDO_UNDO_MISMATCH");
        }
    }

    private static List<Cell> typed(TableSchema schema,Map<String,String> image){
        if(image.size()!=schema.columns.size())throw invalid("ORACLE_FULL_ROW_IMAGE_REQUIRED");
        List<Cell> values=new ArrayList<>(schema.columns.size());
        for(TableSchema.Column column:schema.columns){
            if(!image.containsKey(column.name))throw invalid("ORACLE_FULL_ROW_IMAGE_REQUIRED");
            String value=image.get(column.name);
            if(value==null&&!column.nullable)throw invalid("ORACLE_REDO_UNEXPECTED_NULL");
            if(value!=null)switch(column.type){
                case STRING:break;
                case INT64:case DECIMAL:value=number(column,value);break;
                default:throw invalid("ORACLE_REDO_COLUMN_TYPE_UNSUPPORTED");
            }
            values.add(Cell.value(value));
        }
        return values;
    }

    private static String number(TableSchema.Column column,String value){
        try{
            if(column.type==TableSchema.Type.INT64)return Long.toString(Long.parseLong(value));
            return new BigDecimal(value).setScale(column.scale).toPlainString();
        }catch(ArithmeticException|NumberFormatException invalid){
            throw invalid("ORACLE_REDO_NUMERIC_INVALID");
        }
    }

    private static IllegalStateException invalid(String code){return new IllegalStateException(code);}

    private static final class Statement {
        Change.Operation operation;
        String owner,table;
        final Map<String,String> values=new LinkedHashMap<>(),predicates=new LinkedHashMap<>();
    }

    private static final class Parser {
        private final String sql;
        private final Matcher tokens;
        private int offset,kind;
        private String token;

        Parser(String sql){
            if(sql==null||sql.isEmpty()||sql.length()>16000)throw invalid("ORACLE_REDO_SIZE_UNSUPPORTED");
            this.sql=sql;
            tokens=TOKEN.matcher(sql);
            advance();
        }

        private void advance(){
            int next=offset;
            while(next<sql.length()&&Character.isWhitespace(sql.charAt(next)))next++;
            if(next==sql.length()){
                kind=0;token=null;return;
            }
            if(!tokens.find()||tokens.start()!=offset)throw invalid("ORACLE_REDO_SYNTAX_UNSUPPORTED");
            offset=tokens.end();
            for(kind=1;kind<=5;kind++)if(tokens.group(kind)!=null){token=tokens.group(kind);return;}
            throw invalid("ORACLE_REDO_SYNTAX_UNSUPPORTED");
        }

        private boolean take(String expected){
            if((kind==3||kind==5)&&expected.equalsIgnoreCase(token)){advance();return true;}
            return false;
        }

        private void require(String value){
            if(!take(value))throw invalid("ORACLE_REDO_SYNTAX_UNSUPPORTED");
        }

        private String identifier(){
            if(kind!=1)throw invalid("ORACLE_REDO_QUOTED_IDENTIFIER_REQUIRED");
            String value=token.replace("\"\"","\"");
            advance();
            return value;
        }

        private String literal(){
            if(take("NULL"))return null;
            if(kind!=2&&kind!=4)throw invalid("ORACLE_REDO_LITERAL_UNSUPPORTED");
            String value=kind==2?token.replace("''","'"):token;
            advance();
            return value.isEmpty()?null:value;
        }

        private void field(Map<String,String> values,String name,String value){
            if(values.containsKey(name))throw invalid("ORACLE_REDO_DUPLICATE_COLUMN");
            values.put(name,value);
        }

        Statement parse(){
            Statement result=new Statement();
            if(take("INSERT")){require("INTO");result.operation=Change.Operation.INSERT;}
            else if(take("UPDATE"))result.operation=Change.Operation.UPDATE;
            else if(take("DELETE")){require("FROM");result.operation=Change.Operation.DELETE;}
            else throw invalid("ORACLE_REDO_OPERATION_UNSUPPORTED");
            result.owner=identifier();
            require(".");
            result.table=identifier();
            if(result.operation==Change.Operation.INSERT){
                List<String> columns=new ArrayList<>();
                require("(");
                do columns.add(identifier());while(take(","));
                require(")");require("VALUES");require("(");
                for(int index=0;index<columns.size();index++){
                    if(index>0)require(",");
                    field(result.values,columns.get(index),literal());
                }
                require(")");
            }else{
                if(result.operation==Change.Operation.UPDATE){
                    require("SET");
                    do{
                        String column=identifier();require("=");field(result.values,column,literal());
                    }while(take(","));
                }
                require("WHERE");
                boolean rowIdFound=false;
                do{
                    if(take("ROWID")){
                        require("=");
                        if(rowIdFound||literal()==null)throw invalid("ORACLE_REDO_ROWID_INVALID");
                        rowIdFound=true;
                    }else{
                        String column=identifier();
                        if(take("IS")){
                            require("NULL");field(result.predicates,column,null);
                        }else{
                            require("=");field(result.predicates,column,literal());
                        }
                    }
                }while(take("AND"));
            }
            take(";");
            if(kind!=0)throw invalid("ORACLE_REDO_TRAILING_SQL");
            return result;
        }
    }
}
